class Solution:
    def removeInterval(self, intervals: list[list[int]], toBeRemoved: list[int]) -> list[list[int]]:
        res = []
        lo, hi = toBeRemoved
        for a, b in intervals:
            if b <= lo or a >= hi:
                res.append([a, b])
            else:
                if a < lo:
                    res.append([a, lo])
                if b > hi:
                    res.append([hi, b])
        return res

